// Small, dependency-free validator for the JSON Schema subset generated by pack-template.
// Cross-field timing/media validation remains in render-engine.mjs --plan.
export function validateInputs(value, schema, at = 'inputs') {
  const errors = [];
  const check = (v, s, p) => {
    if (s.oneOf) {
      const matches = s.oneOf.filter(branch => validateInputs(v, branch, p).length === 0);
      if (matches.length !== 1) errors.push(`${p}: expected exactly one allowed shape`);
      return;
    }
    if (s.const !== undefined && v !== s.const) errors.push(`${p}: expected ${JSON.stringify(s.const)}`);
    if (s.enum && !s.enum.includes(v)) errors.push(`${p}: expected ${s.enum.join(' / ')}`);
    if (s.type === 'object') {
      if (!v || typeof v !== 'object' || Array.isArray(v)) { errors.push(`${p}: expected object`); return; }
      for (const key of s.required || []) if (!Object.hasOwn(v, key)) errors.push(`${p}.${key}: required`);
      for (const [key, val] of Object.entries(v)) {
        if (s.properties && Object.hasOwn(s.properties, key)) check(val, s.properties[key], `${p}.${key}`);
        else if (s.additionalProperties === false) errors.push(`${p}.${key}: unknown field`);
      }
    } else if (s.type === 'array') {
      if (!Array.isArray(v)) { errors.push(`${p}: expected array`); return; }
      if (s.minItems != null && v.length < s.minItems) errors.push(`${p}: too few items`);
      if (s.maxItems != null && v.length > s.maxItems) errors.push(`${p}: too many items`);
      v.forEach((item, i) => check(item, s.items || {}, `${p}[${i}]`));
    } else if (s.type === 'string') {
      if (typeof v !== 'string') { errors.push(`${p}: expected string`); return; }
      const length = [...(s['x-highlightAware'] ? v.replace(/\*/g, '') : v)].length;
      if (s.maxLength != null && length > s.maxLength) errors.push(`${p}: text exceeds ${s.maxLength} characters`);
      if (s.minLength != null && length < s.minLength) errors.push(`${p}: empty text`);
      if (s.pattern && !(new RegExp(s.pattern, 'u')).test(v)) errors.push(`${p}: invalid format`);
    } else if (s.type === 'number' || s.type === 'integer') {
      if (typeof v !== 'number' || !Number.isFinite(v) || (s.type === 'integer' && !Number.isInteger(v))) { errors.push(`${p}: expected ${s.type}`); return; }
      if (s.minimum != null && v < s.minimum) errors.push(`${p}: below ${s.minimum}`);
      if (s.maximum != null && v > s.maximum) errors.push(`${p}: above ${s.maximum}`);
    } else if (s.type === 'boolean' && typeof v !== 'boolean') errors.push(`${p}: expected boolean`);
  };
  check(value, schema, at);
  return errors;
}
